// Self-rescheduling poll loop; interval from MODBUS_POLL_MS.
const pollMs = Math.max(500, Number(env.get('MODBUS_POLL_MS') || 5000));
const baseAddress = Number(env.get('MODBUS_BASE_ADDRESS') || 19000);
const unitId = Number(env.get('MODBUS_UNIT_ID') || 1);

const existing = context.get('poll_timer');
if (existing) clearTimeout(existing);

function firePoll() {
    node.send({
        cycle_started_at: new Date().toISOString(),
        payload: { value: '', fc: 3, unitid: unitId, address: baseAddress, quantity: 66 }
    });
    context.set('poll_timer', setTimeout(firePoll, pollMs));
}
firePoll();
return null;

// Decode Janitza-shaped float32 register pairs (big-endian ABCD).
const OFFSETS = {
    active_power_l1_w: 0,
    active_power_l2_w: 2,
    active_power_l3_w: 4,
    active_power_total_w: 6,
    voltage_l1_v: 20,
    voltage_l2_v: 22,
    voltage_l3_v: 24,
    current_l1_a: 40,
    current_l2_a: 42,
    current_l3_a: 44,
    power_factor: 60,
    total_energy_kwh: 62,
    frequency_hz: 64
};

function registersToFloat32(high, low) {
    const buf = Buffer.alloc(4);
    buf.writeUInt16BE(high, 0);
    buf.writeUInt16BE(low, 2);
    return buf.readFloatBE(0);
}

const raw = Array.isArray(msg.payload) ? msg.payload
    : (msg.payload && Array.isArray(msg.payload.data)) ? msg.payload.data
    : null;

if (!raw || raw.length < 66) {
    node.error('modbus-client: incomplete register block (' + (raw ? raw.length : 'none') + '/66)', msg);
    return null;
}

const readings = {};
for (const [metric, offset] of Object.entries(OFFSETS)) {
    const value = registersToFloat32(raw[offset], raw[offset + 1]);
    if (!Number.isFinite(value)) {
        node.error('modbus-client: non-finite value for ' + metric, msg);
        return null;
    }
    readings[metric] = value;
}

msg.readings = readings;
msg.raw_registers = raw.slice(0, 66);
return msg;

// Build the industrial ingestion envelope and the Kafka producer msg.
const host = env.get('MODBUS_HOST') || '127.0.0.1';
const port = env.get('MODBUS_PORT') || '5020';
const unitId = env.get('MODBUS_UNIT_ID') || '1';
const siteId = env.get('INDING_SITE_ID') || 'site-001';
const deviceId = env.get('MODBUS_DEVICE_ID') || 'janitza-umg96rm-001';
const sourceEndpoint = 'modbus-tcp://' + host + ':' + port + '/' + unitId;
const sourceTimestamp = msg.cycle_started_at || new Date().toISOString();

const envelope = {
    schema_version: '1.0',
    event_id: sourceEndpoint + '|' + deviceId + '|' + sourceTimestamp,
    ingest_timestamp: new Date().toISOString(),
    source_protocol: 'modbus-tcp',
    source_endpoint: sourceEndpoint,
    site_id: siteId,
    device_id: deviceId,
    source_timestamp: sourceTimestamp,
    quality: 'good',
    readings: msg.readings,
    raw_payload: JSON.stringify(msg.raw_registers)
};

const m = global.get('metrics') || {};
m.facis_inding_modbus_published_total = (m.facis_inding_modbus_published_total || 0) + 1;
global.set('metrics', m);

return {
    topic: env.get('MODBUS_INGEST_TOPIC') || 'modbus.ingest.raw',
    key: deviceId,
    payload: JSON.stringify(envelope),
    _inding_envelope: envelope,
    _inding_device: deviceId,
    _inding_protocol: 'modbus-tcp'
};

// Route any error on this tab to the shared DLQ with a typed envelope.
let errorType = 'read';
if (msg && msg._inding_envelope) errorType = 'publish';
else if (msg && msg.readings) errorType = 'validate';

return {
    payload: {
        error_type: errorType,
        error_message: msg && msg.error ? (msg.error.message || String(msg.error)) : 'unknown error',
        error_timestamp: new Date().toISOString(),
        source_protocol: 'modbus-tcp',
        device_id: (msg && msg._inding_device) || env.get('MODBUS_DEVICE_ID') || null,
        original_envelope: (msg && msg._inding_envelope) || null
    }
};
